def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    opp_pressure = max(opp_pressure, bid)

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = competitors - expected_units

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0
    threat_bid = max(highest_prev, opp_pressure)

    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2
    abundant = supply >= 22
    tight = supply <= 18

    if critical:
        base = max(0.92 * DAILY_SALARY, threat_bid + 2.0)
    elif urgent:
        base = max(0.78 * DAILY_SALARY, avg_prev + 3.0)
    else:
        if abundant:
            base = 0.28 * DAILY_SALARY
        elif tight:
            base = max(0.52 * DAILY_SALARY, avg_prev + 1.5)
        else:
            base = max(0.40 * DAILY_SALARY, avg_prev)

    if scarcity > 2.5:
        base += 10.0
    elif scarcity > 1.5:
        base += 6.0
    elif scarcity < 0.5:
        base -= 5.0

    if threat_bid >= 100 and not urgent:
        base = min(base, 0.42 * DAILY_SALARY)
    elif threat_bid >= 80 and urgent:
        base = max(base, 0.82 * DAILY_SALARY)

    remaining_days = max(1, 10 - day)
    reserve_target = remaining_days * 18.0
    if budget < reserve_target and not urgent:
        base *= 0.82

    if day >= 8 and hp >= 5 and no_water == 0:
        base *= 0.9

    bid = max(0.0, min(float(budget), base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    competitive_bid_base = DAILY_SALARY * 0.7

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        if max_prev_bid > DAILY_SALARY * 0.6:
            competitive_bid_base = max_prev_bid + 5
        else:
            competitive_bid_base = max(competitive_bid_base, max_prev_bid + 10)

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    final_bid = competitive_bid_base

    if my_hp <= 2:
        final_bid = DAILY_SALARY * 0.95
        if current_day > EPISODE_DAYS / 2 and my_budget > DAILY_SALARY * 2:
            final_bid = DAILY_SALARY * 1.1
    elif my_hp <= 5:
        final_bid = max(final_bid, DAILY_SALARY * 0.8)
        final_bid += 5
    else:
        final_bid = max(final_bid, DAILY_SALARY * 0.65)
        if my_budget > DAILY_SALARY * 3:
            final_bid += 10

    final_bid = max(1.0, min(my_budget, final_bid))

    return final_bid

def get_bid(day_context, my_status, opponents_status):
